use crate::ipc::{IpcError, IpcErrorCode};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs::{self, File};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedWorktree {
    pub path: String,
    pub branch: String,
    pub head: String,
    pub is_main: bool,
    pub is_locked: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedTab {
    pub id: String,
    pub session_id: String,
    pub label: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub custom_title: Option<String>,
    pub worktree_path: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub pane_tree: Option<serde_json::Value>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub session_ids_by_leaf_id: Option<HashMap<String, String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub active_leaf_id: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedLayout {
    pub split_mode: String,
    pub primary_tab_id: Option<String>,
    pub secondary_tab_id: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub active_tab_id: Option<String>,
    pub tabs: Vec<PersistedTab>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedTerminalSession {
    pub session_id: String,
    pub worktree_path: String,
    pub cwd: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub last_command: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub recent_scrollback: Option<String>,
    pub created_at: u64,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedWorkspace {
    pub workspace_id: String,
    pub repo_root: PathBuf,
    pub worktrees: Vec<PersistedWorktree>,
    pub active_worktree_path: Option<String>,
    pub layout: PersistedLayout,
    pub terminal_sessions: HashMap<String, PersistedTerminalSession>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PersistedWorkspaceSession {
    pub version: u32,
    pub timestamp: u64,
    pub active_workspace_id: String,
    pub workspaces: HashMap<String, PersistedWorkspace>,
}

pub fn save_session_to_path(
    path: &Path,
    session: &PersistedWorkspaceSession,
) -> Result<(), IpcError> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to create directory for session state: {}", e),
            )
        })?;
    }

    let serialized = serde_json::to_string_pretty(session).map_err(|e| {
        IpcError::new(
            IpcErrorCode::ParseError,
            format!("Failed to serialize session state: {}", e),
        )
    })?;

    let tmp_path = path.with_extension("json.tmp");

    // Durable atomic write: write -> sync_all -> rename -> parent fsync
    {
        use std::io::Write;
        let mut file = File::create(&tmp_path).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to create temporary session file: {}", e),
            )
        })?;
        file.write_all(serialized.as_bytes()).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to write session state: {}", e),
            )
        })?;
        file.sync_all().map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to fsync temporary session file: {}", e),
            )
        })?;
    }

    fs::rename(&tmp_path, path).map_err(|e| {
        IpcError::new(
            IpcErrorCode::IoError,
            format!("Failed to atomically rename session state file: {}", e),
        )
    })?;

    // Parent directory fsync
    if let Some(parent) = path.parent() {
        if let Ok(dir_file) = File::open(parent) {
            let _ = dir_file.sync_all();
        }
    }

    Ok(())
}

pub fn load_session_from_path(path: &Path) -> Result<Option<PersistedWorkspaceSession>, IpcError> {
    if !path.exists() {
        return Ok(None);
    }

    let content = fs::read_to_string(path).map_err(|e| {
        IpcError::new(
            IpcErrorCode::IoError,
            format!("Failed to read session state file: {}", e),
        )
    })?;

    match serde_json::from_str::<PersistedWorkspaceSession>(&content) {
        Ok(session) => {
            if session.version != 1 {
                eprintln!("Warning: Unsupported session version {}, ignoring.", session.version);
                return Ok(None);
            }
            Ok(Some(session))
        }
        Err(err) => {
            let backup_path = path.with_extension("json.corrupted");
            let _ = fs::rename(path, backup_path);
            eprintln!(
                "Warning: Session state file was corrupted ({}), moved to backup.",
                err
            );
            Ok(None)
        }
    }
}

pub fn clear_session_from_path(path: &Path) -> Result<(), IpcError> {
    if path.exists() {
        fs::remove_file(path).map_err(|e| {
            IpcError::new(
                IpcErrorCode::IoError,
                format!("Failed to remove session state file: {}", e),
            )
        })?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn test_session_save_load_clear_cycle() {
        let dir = tempdir().unwrap();
        let session_file = dir.path().join("session_state.json");

        let mut workspaces = HashMap::new();
        workspaces.insert(
            "default".to_string(),
            PersistedWorkspace {
                workspace_id: "default".to_string(),
                repo_root: PathBuf::from("/tmp/repo"),
                worktrees: vec![PersistedWorktree {
                    path: "/tmp/repo".to_string(),
                    branch: "main".to_string(),
                    head: "abcdef".to_string(),
                    is_main: true,
                    is_locked: false,
                }],
                active_worktree_path: Some("/tmp/repo".to_string()),
                layout: PersistedLayout {
                    split_mode: "none".to_string(),
                    primary_tab_id: Some("tab-1".to_string()),
                    secondary_tab_id: None,
                    active_tab_id: Some("tab-1".to_string()),
                    tabs: vec![PersistedTab {
                        id: "tab-1".to_string(),
                        session_id: "term-1".to_string(),
                        label: "main".to_string(),
                        custom_title: None,
                        worktree_path: "/tmp/repo".to_string(),
                        pane_tree: None,
                        session_ids_by_leaf_id: None,
                        active_leaf_id: None,
                    }],
                },
                terminal_sessions: HashMap::new(),
            },
        );

        let session = PersistedWorkspaceSession {
            version: 1,
            timestamp: 1234567890,
            active_workspace_id: "default".to_string(),
            workspaces,
        };

        let loaded = load_session_from_path(&session_file).unwrap();
        assert!(loaded.is_none());

        save_session_to_path(&session_file, &session).unwrap();
        assert!(session_file.exists());

        let loaded = load_session_from_path(&session_file).unwrap();
        assert!(loaded.is_some());
        let loaded_session = loaded.unwrap();
        assert_eq!(loaded_session.version, 1);
        assert_eq!(loaded_session.active_workspace_id, "default");
        assert_eq!(
            loaded_session.workspaces["default"].repo_root,
            PathBuf::from("/tmp/repo")
        );

        clear_session_from_path(&session_file).unwrap();
        assert!(!session_file.exists());
        let loaded = load_session_from_path(&session_file).unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn test_corrupted_session_recovery() {
        let dir = tempdir().unwrap();
        let session_file = dir.path().join("session_state.json");

        fs::write(&session_file, "{ broken json ...").unwrap();

        let loaded = load_session_from_path(&session_file).unwrap();
        assert!(loaded.is_none());
        assert!(!session_file.exists());
        assert!(dir.path().join("session_state.json.corrupted").exists());
    }
}

use ferryx_lib::session::{
    clear_session_from_path, load_session_from_path, save_session_to_path, PersistedLayout,
    PersistedTab, PersistedWorkspace, PersistedWorkspaceSession, PersistedWorktree,
};
use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;
use tempfile::tempdir;

#[test]
fn test_session_lifecycle_integration() {
    let dir = tempdir().unwrap();
    let session_file = dir.path().join("session_state.json");

    let mut workspaces = HashMap::new();
    workspaces.insert(
        "default".to_string(),
        PersistedWorkspace {
            workspace_id: "default".to_string(),
            repo_root: PathBuf::from("/tmp/repo"),
            worktrees: vec![PersistedWorktree {
                path: "/tmp/repo".to_string(),
                branch: "main".to_string(),
                head: "abcdef".to_string(),
                is_main: true,
                is_locked: false,
            }],
            active_worktree_path: Some("/tmp/repo".to_string()),
            layout: PersistedLayout {
                split_mode: "none".to_string(),
                primary_tab_id: Some("tab-1".to_string()),
                secondary_tab_id: None,
                active_tab_id: Some("tab-1".to_string()),
                tabs: vec![PersistedTab {
                    id: "tab-1".to_string(),
                    session_id: "term-1".to_string(),
                    label: "main".to_string(),
                    custom_title: None,
                    worktree_path: "/tmp/repo".to_string(),
                    pane_tree: None,
                    session_ids_by_leaf_id: None,
                    active_leaf_id: None,
                }],
            },
            terminal_sessions: HashMap::new(),
        },
    );

    let session = PersistedWorkspaceSession {
        version: 1,
        timestamp: 1787292000,
        active_workspace_id: "default".to_string(),
        workspaces,
    };

    let loaded = load_session_from_path(&session_file).unwrap();
    assert!(loaded.is_none());

    save_session_to_path(&session_file, &session).unwrap();
    assert!(session_file.exists());

    let loaded = load_session_from_path(&session_file).unwrap().unwrap();
    assert_eq!(loaded.version, 1);
    assert_eq!(loaded.active_workspace_id, "default");
    assert_eq!(
        loaded.workspaces["default"].repo_root,
        PathBuf::from("/tmp/repo")
    );

    clear_session_from_path(&session_file).unwrap();
    assert!(!session_file.exists());
}

#[test]
fn test_version_2_session_envelope_restore_preserves_multiple_workspaces() {
    let dir = tempdir().unwrap();
    let session_file = dir.path().join("session_state.json");

    let v2_payload = serde_json::json!({
        "version": 2,
        "timestamp": 1787292000000u64,
        "activeWorkspaceId": "alpha",
        "workspaces": {
            "alpha": {
                "workspaceId": "alpha",
                "repoRoot": "/workspace/alpha",
                "worktrees": [
                    {
                        "path": "/workspace/alpha",
                        "branch": "refs/heads/main",
                        "head": "111111",
                        "isMain": true,
                        "isLocked": false
                    },
                    {
                        "path": "/workspace/alpha/feature",
                        "branch": "refs/heads/feature-a",
                        "head": "222222",
                        "isMain": false,
                        "isLocked": false
                    }
                ],
                "activeWorktreePath": "/workspace/alpha",
                "layout": {
                    "splitMode": "vertical",
                    "primaryTabId": "tab-term-1",
                    "secondaryTabId": "tab-browser-1",
                    "activeTabId": "tab-term-1",
                    "tabs": [
                        {
                            "id": "tab-term-1",
                            "kind": "terminal",
                            "label": "Terminal 1",
                            "pinned": false,
                            "terminal": {
                                "primarySessionId": "sess-alpha-1",
                                "paneTree": {
                                    "type": "leaf",
                                    "leafId": "leaf-term-1"
                                },
                                "sessionIdsByLeafId": {
                                    "leaf-term-1": "sess-alpha-1"
                                },
                                "activeLeafId": "leaf-term-1",
                                "expandedLeafId": null
                            }
                        },
                        {
                            "id": "tab-browser-1",
                            "kind": "browser",
                            "label": "Docs",
                            "pinned": true,
                            "browser": {
                                "browserId": "browser-alpha-1",
                                "url": "https://example.com/docs",
                                "title": "Documentation",
                                "loading": false,
                                "canGoBack": true,
                                "canGoForward": false
                            }
                        }
                    ],
                    "tabGroups": [
                        {
                            "id": "group-alpha-1",
                            "tabIds": ["tab-term-1", "tab-browser-1"],
                            "activeTabId": "tab-term-1"
                        }
                    ],
                    "tabGroupLayout": null,
                    "focusedGroupId": "group-alpha-1"
                },
                "terminalSessions": {
                    "sess-alpha-1": {
                        "localSessionId": "sess-alpha-1",
                        "backendSessionId": "backend-pty-alpha",
                        "worktreePath": "/workspace/alpha",
                        "cwd": "/workspace/alpha",
                        "createdAt": 1787292000000u64
                    }
                }
            },
            "beta": {
                "workspaceId": "beta",
                "repoRoot": "/workspace/beta",
                "worktrees": [
                    {
                        "path": "/workspace/beta",
                        "branch": "refs/heads/main",
                        "head": "333333",
                        "isMain": true,
                        "isLocked": false
                    }
                ],
                "activeWorktreePath": "/workspace/beta",
                "layout": {
                    "splitMode": "none",
                    "primaryTabId": "tab-beta-1",
                    "secondaryTabId": null,
                    "activeTabId": "tab-beta-1",
                    "tabs": [
                        {
                            "id": "tab-beta-1",
                            "kind": "terminal",
                            "label": "Beta Terminal",
                            "pinned": false,
                            "terminal": {
                                "primarySessionId": "sess-beta-1",
                                "paneTree": {
                                    "type": "leaf",
                                    "leafId": "leaf-beta-1"
                                },
                                "sessionIdsByLeafId": {
                                    "leaf-beta-1": "sess-beta-1"
                                },
                                "activeLeafId": "leaf-beta-1",
                                "expandedLeafId": null
                            }
                        }
                    ],
                    "tabGroups": [],
                    "tabGroupLayout": null,
                    "focusedGroupId": null
                },
                "terminalSessions": {
                    "sess-beta-1": {
                        "localSessionId": "sess-beta-1",
                        "backendSessionId": null,
                        "worktreePath": "/workspace/beta",
                        "cwd": "/workspace/beta",
                        "createdAt": 1787292000000u64
                    }
                }
            }
        }
    });

    let json_bytes = serde_json::to_vec_pretty(&v2_payload).unwrap();
    fs::write(&session_file, json_bytes).unwrap();
    assert!(session_file.exists());

    let loaded = load_session_from_path(&session_file)
        .expect("loader should not return io error")
        .expect("native session loader must accept version-2 session envelope and restore workspaces");

    assert_eq!(loaded.version, 2);
    assert_eq!(loaded.active_workspace_id, "alpha");
    assert_eq!(loaded.workspaces.len(), 2);
    assert!(
        loaded.workspaces.contains_key("alpha"),
        "workspace alpha must survive"
    );
    assert!(
        loaded.workspaces.contains_key("beta"),
        "workspace beta must survive"
    );
    assert_eq!(
        loaded.workspaces["alpha"].repo_root,
        PathBuf::from("/workspace/alpha")
    );
    assert_eq!(
        loaded.workspaces["beta"].repo_root,
        PathBuf::from("/workspace/beta")
    );
    assert_eq!(loaded.workspaces["alpha"].worktrees.len(), 2);
    assert_eq!(loaded.workspaces["beta"].worktrees.len(), 1);
}

