+pub mod ipc;
+pub mod terminal;
+pub mod worktree;
+
+use ipc::*;
+use std::sync::Arc;
+use terminal::PtyManager;
+use worktree::WorktreeManager;
+
+pub fn create_app<R: tauri::Runtime>(builder: tauri::Builder<R>) -> tauri::Builder<R> {
+    let pty_manager = Arc::new(PtyManager::new());
+    let repo_root = std::env::current_dir().unwrap_or_else(|_| std::path::PathBuf::from("."));
+    let worktree_manager = WorktreeManager::new(repo_root);
+
+    builder
+        .manage(pty_manager)
+        .manage(worktree_manager)
+        .invoke_handler(tauri::generate_handler![
+            cmd_terminal_spawn,
+            cmd_terminal_write,
+            cmd_terminal_resize,
+            cmd_terminal_close,
+            cmd_terminal_list,
+            cmd_worktree_list,
+            cmd_worktree_create,
+            cmd_worktree_delete,
+            cmd_worktree_status,
+        ])
+}
+
+#[cfg_attr(mobile, tauri::mobile_entry_point)]
+pub fn run() {
+    create_app(tauri::Builder::default())
+        .run(tauri::generate_context!())
+        .expect("error while running tauri application");
+}
